import json
import sys
from pathlib import Path

def main():
    data = []
    for i in range(100):
        record = {
            "id": i,
            "value": f"item_{i}",
            "active": i % 2 == 0
        }
        data.append(record)
    with open("output.jsonl", "w") as f:
        for item in data:
            f.write(json.dumps(item) + "\n")

if __name__ == "__main__":
    main()
